package com.jnapanam.sportszone.tournament.model;import com.jnapanam.sportszone.catalog.model.Facility;import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity@Table(name="tournament_fixtures")public class TournamentFixture{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tournament_id")private Tournament tournament;@Column(name="round_number",nullable=false)private int roundNumber;@Column(name="match_number",nullable=false)private int matchNumber;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="home_team_id")private TournamentTeam homeTeam;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="away_team_id")private TournamentTeam awayTeam;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="facility_id")private Facility facility;@Column(name="scheduled_at")private Instant scheduledAt;@Column(name="home_score")private Integer homeScore;@Column(name="away_score")private Integer awayScore;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="winner_team_id")private TournamentTeam winner;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private FixtureStatus status;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected TournamentFixture(){}public TournamentFixture(Tournament t,int r,int m,TournamentTeam h,TournamentTeam a){id=UUID.randomUUID();tournament=t;roundNumber=r;matchNumber=m;homeTeam=h;awayTeam=a;status=FixtureStatus.SCHEDULED;updatedAt=Instant.now();}public void schedule(Facility f,Instant at){facility=f;scheduledAt=at;updatedAt=Instant.now();}public void result(int hs,int as){if(awayTeam==null)throw new IllegalStateException("Bye fixture has no result");homeScore=hs;awayScore=as;winner=hs>as?homeTeam:as>hs?awayTeam:null;status=FixtureStatus.COMPLETED;updatedAt=Instant.now();}public UUID getId(){return id;}public Tournament getTournament(){return tournament;}public int getRoundNumber(){return roundNumber;}public int getMatchNumber(){return matchNumber;}public TournamentTeam getHomeTeam(){return homeTeam;}public TournamentTeam getAwayTeam(){return awayTeam;}public Facility getFacility(){return facility;}public Instant getScheduledAt(){return scheduledAt;}public Integer getHomeScore(){return homeScore;}public Integer getAwayScore(){return awayScore;}public TournamentTeam getWinner(){return winner;}public FixtureStatus getStatus(){return status;}}
